/**
 * "Nom", as typed; surrounding spaces are removed, and a name made only of spaces is refused
 * with `400 request.invalid`.
 * @minLength 1
 * @maxLength 80
 */
export type ListName = string;

/**
 * The dates and the goal of a sprint, the two dates always together; a `goal` left out is
 * unchanged by a patch and `null` at a creation.
 */
export interface SprintInput {
  /** "Début". */
  startDate: string;
  /** "Fin", on or after `startDate` ("La fin doit suivre le début."). */
  endDate: string;
  /**
     * "Objectif du sprint", trimmed; `null` or an empty text for none.
     * @maxLength 300
     * @nullable
     */
  goal?: string | null;
}

/**
 * A new list or sprint. The members with a default declare their values themselves, the
 * values of `LookIcon` and `LookColor`.
 */
export interface ListCreation {
  name: ListName;
  /**
     * One of the icons of `LookIcon`; `null`, the default, for the default icon.
     * @nullable
     */
  icon?: ListCreationIcon;
  /** One of the colors of `LookColor`; `gris` by default. */
  color?: ListCreationColor;
  /**
     * The dates and the goal to create a sprint ("Sprint"), both dates required; absent or
     * `null` for a list.
     */
  sprint?: SprintInput | null;
  /**
     * The switch "Accès de l’organisation" of the new list; absent, it is on (`true`), as
     * for every list created before the switch existed.
     */
  organizationAccess?: boolean;
}

/**
 * JSON Merge Patch of a list; an empty object changes nothing. `sprint: null` makes a sprint
 * a list again, and drops its dates and goal.
 */
export interface ListPatch {
  name?: ListName;
  icon?: LookIcon | null;
  color?: LookColor;
  sprint?: SprintInput | null;
  /**
     * Turns the switch "Accès de l’organisation" on or off ("Tous les membres de Atelier
     * Nord peuvent voir cette liste").
     */
  organizationAccess?: boolean;
}

/**
 * Counts of the top-level tasks of a list, subtasks left out, as the sidebar, the list cards
 * and the sprint progress count them. The progress of a list ("12 / 32 terminées", "38 %")
 * is `done` out of `total` minus `cancelled`.
 */
export interface TaskCounts {
  /**
     * Every top-level task of the list ("32 tâches").
     * @minimum 0
     */
  total: number;
  /**
     * The tasks that are not closed, of the categories `open` and `active` ("14 ouvertes").
     * @minimum 0
     */
  open: number;
  /**
     * The tasks of the key `done` ("12 / 32 terminées").
     * @minimum 0
     */
  done: number;
  /**
     * The tasks of the key `cancelled`, left out of the progress.
     * @minimum 0
     */
  cancelled: number;
  /**
     * The tasks that are not closed and whose due date is before the `today` of the request
     * ("3 en retard").
     * @minimum 0
     */
  late: number;
}

/**
 * A list with the counts of its tasks.
 */
export interface ListSummary {
  list: TaskList;
  counts: TaskCounts;
}

/**
 * One item of a checklist ("Une checklist sert aux petites étapes sans statut ni assigné.").
 */
export interface ChecklistItem {
  id: string;
  /** "Élément de checklist", 300 characters at most. */
  text: string;
  /** Ticked ("Terminer") or not ("Rouvrir"). */
  done: boolean;
}

/**
 * A task, with its description and its checklist.
 */
export interface Task {
  /** Whether this task is a milestone; absence means the producer did not report it. */
  milestone?: boolean;
  recurrence?: Recurrence;
  /** Structured spans in the current Markdown description. */
  descriptionMentions?: Mention[];
  nextOccurrenceKey?: TaskKey;
  customFieldValues?: TaskCustomFieldValues;
  key: TaskKey;
  /** "Nom de la tâche", 300 characters at most. */
  name: string;
  /**
     * "Description", Markdown, 50,000 characters at most; `null` when there is none.
     * @nullable
     */
  description: string | null;
  status: StatusKey;
  /** Why the task was cancelled; `null` unless its status is `cancelled`. */
  cancelReason: CancelReason | null;
  /**
     * "Précision" of the cancellation, 500 characters at most; `null` when there is none or
     * the task is not cancelled.
     * @nullable
     */
  cancelNote: string | null;
  priority: PriorityKey;
  /** "Assignés", 20 at most, in the order they were assigned. */
  assignees: UserRef[];
  /**
     * "Échéance"; `null` when there is none.
     * @nullable
     */
  dueDate: string | null;
  /**
     * First day of the work; `null` when there is none, always `null` without a due date.
     * @nullable
     */
  startDate: string | null;
  /**
     * "Estimation", in whole minutes, 60,000 at most; `null` when there is none.
     * @minimum 1
     * @nullable
     */
  estimateMinutes: number | null;
  /** "Étiquettes", 20 at most, in the order they were added. */
  labels: string[];
  /** The parent of a subtask; `null` for a top-level task. */
  parentKey: TaskKey | null;
  listId: string;
  spaceId: string;
  subtaskCounts: SubtaskCounts;
  /** "Checklist", 100 items at most, in the order they were added. */
  checklist: ChecklistItem[];
  checklistCounts: ChecklistCounts;
  /**
     * When the task last entered `done`; `null` while its status is not `done`.
     * @nullable
     */
  completedAt: string | null;
  createdAt: string;
  createdBy: Actor;
  /** When the task last changed, its assignees, labels and checklist included. */
  updatedAt: string;
  /**
     * Version of the task, also sent as `ETag`; every change adds one, a change of its
     * assignees, labels or checklist, an archive and a restoration included.
     * @minimum 1
     */
  version: number;
  /**
     * When the task was archived, with the subtree it heads or belongs to ("archivée le 5
     * nov."); `null` for a task that is not. An archived task is left out of every
     * collection and count, reads by its key and refuses changes (`409 task.archived`) until
     * it is restored. Absent, it reads as `null`.
     * @nullable
     */
  archivedAt?: string | null;
  /** Who archived the task; `null` for a task that is not archived. Absent, it reads as `null`. */
  archivedBy?: Actor | null;
}

/**
 * A task named by another resource, with its name and status as they are now.
 */
export interface TaskRef {
  key: TaskKey;
  name: string;
  status: StatusKey;
}

/**
 * "Statut", one of `StatusKey`; `todo` ("À faire") by default.
 */
export type TaskCreationStatus = typeof TaskCreationStatus[keyof typeof TaskCreationStatus];


export const TaskCreationStatus = {
  triage: 'triage',
  backlog: 'backlog',
  todo: 'todo',
  progress: 'progress',
  review: 'review',
  testing: 'testing',
  waiting: 'waiting',
  blocked: 'blocked',
  done: 'done',
  cancelled: 'cancelled',
} as const;

/**
 * "Priorité", one of `PriorityKey`; `moyenne` by default.
 */
export type TaskCreationPriority = typeof TaskCreationPriority[keyof typeof TaskCreationPriority];


export const TaskCreationPriority = {
  urgente: 'urgente',
  haute: 'haute',
  moyenne: 'moyenne',
  basse: 'basse',
} as const;

export interface ChecklistItemCreation {
  /**
     * "Élément de checklist", trimmed; a text made only of spaces is refused with
     * `400 request.invalid`.
     * @minLength 1
     * @maxLength 300
     */
  text: string;
}

/**
 * "Nom de la tâche", as typed; surrounding spaces are removed, and a name made only of spaces
 * is refused with `400 request.invalid`.
 * @minLength 1
 * @maxLength 300
 */
export type TaskName = string;

/**
 * "Description", Markdown; `null` when there is none.
 * @maxLength 50000
 * @nullable
 */
export type TaskDescription = string | null;

/**
 * "Estimation", in whole minutes ("8 h" is `480`); `null` for none.
 * @minimum 1
 * @maximum 60000
 * @nullable
 */
export type EstimateMinutes = number | null;

/**
 * A label ("Étiquette"), trimmed; two labels that differ only by case are the same label.
 * @minLength 1
 * @maxLength 32
 */
export type LabelName = string;

/**
 * A subtask to create with its parent ("Ajouter une sous-tâche (Entrée pour valider)").
 */
export interface SubtaskName {
  name: TaskName;
}

/**
 * A new task. `status` and `priority` declare their values themselves, those of `StatusKey`
 * and `PriorityKey`, with their default.
 */
export interface TaskCreation {
  /**
     * Structured spans in the description; replacing text clears prior spans unless a
     * replacement array is supplied. Invalid
     * spans answer `400 request.invalid`, ineligible recipients `422 mention.recipient-invalid`.
     * @maxItems 20
     */
  descriptionMentions?: Mention[];
  /**
     * A milestone permits only todo, blocked, done and cancelled. Dated milestones have
     * equal start and due dates, undated milestones have both null; estimate is null.
     * Conversion normalizes inherited fields and maps an inherited disallowed status to todo.
     * Conflicting explicit dates or status answer `422 milestone.dates-invalid` or
     * `422 milestone.status-invalid`. Removing the flag keeps normalized fields.
     */
  milestone?: boolean;
  recurrence?: Recurrence;
  /**
     * Checklist text in order; fresh IDs and unchecked items are created atomically.
     * @maxItems 100
     */
  checklist?: ChecklistItemCreation[];
  name: TaskName;
  description?: TaskDescription | null;
  /** "Statut", one of `StatusKey`; `todo` ("À faire") by default. */
  status?: TaskCreationStatus;
  cancelReason?: CancelReasonInput;
  /**
     * "Précision (facultatif)" of a cancellation, trimmed; only with the status `cancelled`.
     * @maxLength 500
     * @nullable
     */
  cancelNote?: string | null;
  /** "Priorité", one of `PriorityKey`; `moyenne` by default. */
  priority?: TaskCreationPriority;
  /**
     * Accounts to assign, current members of the organization other than guests; the same
     * account twice counts once. The creation form sends the caller by default.
     * @maxItems 20
     */
  assigneeIds?: string[];
  /**
     * "Échéance".
     * @nullable
     */
  dueDate?: string | null;
  /**
     * First day of the work; needs a due date, on or before it.
     * @nullable
     */
  startDate?: string | null;
  estimateMinutes?: EstimateMinutes | null;
  /**
     * "Étiquettes"; trimmed, and a label that repeats another without regard to case is ignored.
     * @maxItems 20
     */
  labels?: LabelName[];
  /**
     * Subtasks to create with the task ("Sous-tâches"), in this order. Each takes the next key
     * after the task, its list and its first assignee, the status `todo` and the priority
     * `moyenne`.
     * @maxItems 25
     */
  subtasks?: SubtaskName[];
}

/**
 * "Statut", one of `StatusKey`; `todo` ("À faire") by default.
 */
export type SubtaskCreationStatus = typeof SubtaskCreationStatus[keyof typeof SubtaskCreationStatus];


export const SubtaskCreationStatus = {
  triage: 'triage',
  backlog: 'backlog',
  todo: 'todo',
  progress: 'progress',
  review: 'review',
  testing: 'testing',
  waiting: 'waiting',
  blocked: 'blocked',
  done: 'done',
  cancelled: 'cancelled',
} as const;

/**
 * "Priorité", one of `PriorityKey`; `moyenne` by default.
 */
export type SubtaskCreationPriority = typeof SubtaskCreationPriority[keyof typeof SubtaskCreationPriority];


export const SubtaskCreationPriority = {
  urgente: 'urgente',
  haute: 'haute',
  moyenne: 'moyenne',
  basse: 'basse',
} as const;

/**
 * A subtask created under a task ("Nouvelle sous-tâche"). It takes the list of its parent;
 * without `assigneeIds`, it takes the first assignee of its parent.
 */
export interface SubtaskCreation {
  name: TaskName;
  description?: TaskDescription | null;
  /** "Statut", one of `StatusKey`; `todo` ("À faire") by default. */
  status?: SubtaskCreationStatus;
  cancelReason?: CancelReasonInput;
  /**
     * Only with the status `cancelled`.
     * @maxLength 500
     * @nullable
     */
  cancelNote?: string | null;
  /** "Priorité", one of `PriorityKey`; `moyenne` by default. */
  priority?: SubtaskCreationPriority;
  /**
     * Accounts to assign; absent, the first assignee of the parent, if any.
     * @maxItems 20
     */
  assigneeIds?: string[];
  /** @nullable */
  dueDate?: string | null;
  /**
     * Needs a due date, on or before it.
     * @nullable
     */
  startDate?: string | null;
  estimateMinutes?: EstimateMinutes | null;
  /** @maxItems 20 */
  labels?: LabelName[];
}

/**
 * Merge values by lowercase active field ID in the task's resulting space. Omitted keys are unchanged.
 * A null value clears that entry. A number or string must match the field's immutable type.
 * A value of the designated sprint points field must be nonnegative, including zero.
 */
export interface TaskCustomFieldValuesPatch {[key: string]: number | string | null}

/**
 * JSON Merge Patch of a task; an empty object changes nothing. The assignees, the labels and
 * the checklist are collections: they change through their own routes, and a patch ignores
 * the members it does not declare, `assigneeIds` and `labels` included.
 */
export interface TaskPatch {
  customFieldValues?: TaskCustomFieldValuesPatch;
  /**
     * Structured spans in the description; replacing text clears prior spans unless a
     * replacement array is supplied. A spans-only patch also requires If-Match. Invalid
     * spans answer `400 request.invalid`, ineligible recipients `422 mention.recipient-invalid`.
     * @maxItems 20
     */
  descriptionMentions?: Mention[];
  /**
     * A milestone permits only todo, blocked, done and cancelled. Dated milestones have
     * equal start and due dates, undated milestones have both null; estimate is null.
     * Conversion normalizes inherited fields and maps an inherited disallowed status to todo.
     * Conflicting explicit dates or status answer `422 milestone.dates-invalid` or
     * `422 milestone.status-invalid`. Removing the flag keeps normalized fields.
     */
  milestone?: boolean;
  recurrence?: Recurrence;
  name?: TaskName;
  description?: TaskDescription | null;
  status?: StatusKey;
  /**
     * Required when the status becomes `cancelled`; changes the reason of a cancelled task;
     * refused on a task that is not cancelled after the patch. Leaving `cancelled` clears it.
     */
  cancelReason?: CancelReason | null;
  /**
     * "Précision" of a cancellation, trimmed; `null` clears it.
     * @maxLength 500
     * @nullable
     */
  cancelNote?: string | null;
  priority?: PriorityKey;
  /**
     * New due date; `null` removes it. Without `startDate` in the same patch, the start
     * moves with it and the duration is kept (see `PATCH /v1/tasks/{taskKey}`).
     * @nullable
     */
  dueDate?: string | null;
  /**
     * New first day of the work; `null` removes it.
     * @nullable
     */
  startDate?: string | null;
  estimateMinutes?: EstimateMinutes | null;
  /**
     * The list to move the task to ("Déplacer vers…"), in this space or another; its
     * subtasks follow, and a subtask leaves its parent first.
     */
  listId?: string;
  /**
     * The task to attach this one to ("Devenir sous-tâche de…"), which brings it and its
     * subtasks to the list of the parent; `null` detaches it ("Détacher de CAD-482").
     */
  parentKey?: TaskKey | null;
}

/**
 * A label to add to a task or to remove from it.
 */
export interface LabelChange {
  name: LabelName;
}

/**
 * Empty object `{}`, the body the public route carried.
 */
export interface EmptyRequest { [key: string]: never }

/**
 * JSON Merge Patch of a checklist item; ticking or unticking it is the one change of this version.
 */
export interface ChecklistItemPatch {
  /** `true` ticks the item ("Terminer"), `false` unticks it ("Rouvrir"). */
  done: boolean;
}

/**
 * For `status`, the status before and after.
 */
export type ActivityEntryStatus = {
  from: StatusKey;
  to: StatusKey;
};

/**
 * For `priority`, the priority before and after.
 */
export type ActivityEntryPriority = {
  from: PriorityKey;
  to: PriorityKey;
};

/**
 * For `due`, the due date before and after; `from` is `null` when one is set, `to` when it is removed.
 */
export type ActivityEntryDueDate = {
  /** @nullable */
  from: string | null;
  /** @nullable */
  to: string | null;
};

/**
 * For `assign`, who was assigned (`added: true`) or left the assignees (`added: false`);
 * the person themself when `userId` is the id of the actor.
 */
export type ActivityEntryAssignee = {
  userId: string;
  added: boolean;
};

/**
 * One entry of the activity log of a task ("Activité"); every entry names a task, and an entry
 * about a list or a space would come on a route of its own. The member that names the change
 * is the one of its `kind`: `status`, `priority`, `dueDate`, `assignee` or `commentId`; a creation has
 * none. Comment creation records its ID and an excerpt of the current body; deleting the comment
 * removes the entry. Edits and deletions do not create separate entries. Later versions add kinds: a client shows an unknown kind
 * as "a modifié la tâche".
 */
export interface ActivityEntry {
  /** Comment associated with a comment activity entry. */
  commentId?: string;
  /** Up to 240 Unicode code points of the current comment body. */
  commentExcerpt?: string;
  id: string;
  /** When the change was made; for merged changes, the last of them. */
  occurredAt: string;
  /**
     * `create` records creation, `status` a status change, `priority` a priority change,
     * `due` a due-date change, `assign` an assignment change, and `comment` a new comment.
     * Future kinds may be added; render unknown kinds as a generic task change.
     */
  kind: string;
  actor: Actor;
  task: TaskRef;
  /**
     * The list the task was in when the change was made, an id only, which may be a list the
     * caller no longer sees.
     */
  listId: string;
  /** For `status`, the status before and after. */
  status?: ActivityEntryStatus;
  /** For `priority`, the priority before and after. */
  priority?: ActivityEntryPriority;
  /** For `due`, the due date before and after; `from` is `null` when one is set, `to` when it is removed. */
  dueDate?: ActivityEntryDueDate;
  /**
     * For `assign`, who was assigned (`added: true`) or left the assignees (`added: false`);
     * the person themself when `userId` is the id of the actor.
     */
  assignee?: ActivityEntryAssignee;
}

/**
 * The access of one person to a space or a list ("Personnes ayant accès"), given by someone
 * who manages it. A space or a list holds 200 grants at most. The owner of the space holds
 * none: they always have `edit` ("Propriétaire").
 */
export interface Grant {
  /** Account of the person, a current member or guest of the organization. */
  userId: string;
  role: AccessRoleValue;
  /** When the person was given this role. */
  grantedAt: string;
  grantedBy: Actor;
}

/**
 * A role given by a grant ("Droit d’accès"): `edit` ("Peut modifier"), `comment` ("Peut
 * commenter", which reads like `view` until comments exist) or `view` ("Lecture seule"),
 * from the most to the least. The owner of a space ("Propriétaire") holds no grant: they
 * always have `edit` on it and on its lists.
 */
export type AccessRole = typeof AccessRole[keyof typeof AccessRole];


export const AccessRole = {
  edit: 'edit',
  comment: 'comment',
  view: 'view',
} as const;

/**
 * The role to give ("Droit d’accès"); it replaces the role the person had there.
 */
export interface GrantChange {
  role: AccessRole;
}

/**
 * What a request asks for: `space`, `list` or `task`. Later versions may add targets
 * (`x-extensible-enum`).
 */
export type AccessRequestTargetValue = string;

/**
 * `pending` until someone who manages the target answers, then `approved` or `refused`. Later
 * versions may add states (`x-extensible-enum`).
 */
export type AccessRequestStateValue = string;

/**
 * A request for access, as the people who manage its target read it. The requester never
 * reads it: they learn the answer from the inbox (cadenway-notification-service). It has no
 * `version` of its own to send back: it changes once, from `pending`, and a second answer
 * gets `409 access-request.already-decided`; its events carry `1`, then `2`.
 */
export interface AccessRequest {
  id: string;
  target: AccessRequestTargetValue;
  /** The space of the target. */
  spaceId: string;
  /**
     * The list of a list or task target; `null` for a space.
     * @nullable
     */
  listId: string | null;
  /** The task of a task target, with its name and status as they are now; `null` otherwise. */
  task: TaskRef | null;
  requester: UserRef;
  /**
     * The message of the requester, 500 characters at most; `null` when there is none.
     * @nullable
     */
  message: string | null;
  state: AccessRequestStateValue;
  /** The role an approval gave; `null` while pending or when refused. */
  role: AccessRoleValue | null;
  createdAt: string;
  /**
     * When it was approved or refused; `null` while pending.
     * @nullable
     */
  decidedAt: string | null;
  /** Who approved or refused it; `null` while pending. */
  decidedBy: Actor | null;
}

/**
 * A request for access ("Demander l’accès"): exactly one of `spaceId`, `listId` and
 * `taskKey`, as the link the caller followed names the target; none or several answer
 * `400 request.invalid`.
 */
export interface AccessRequestCreation {
  /** A space to have a role on. */
  spaceId?: string;
  /** A list to see. */
  listId?: string;
  taskKey?: TaskKey;
  /**
     * "Message pour Léa (facultatif)", trimmed; `null` or an empty text for none.
     * @maxLength 500
     * @nullable
     */
  message?: string | null;
}

/**
 * The role an approval gives the requester ("Droit d’accès").
 */
export interface AccessRequestApproval {
  role: AccessRole;
}

/**
 * A list of the archives ("Archives", tab "Listes").
 */
export interface ArchivedList {
  list: TaskList;
  /**
     * Its top-level tasks, subtasks left out ("14 tâches").
     * @minimum 0
     */
  taskCount: number;
}

/**
 * `active` for a list of the sidebar, `archived` for a list of the archives ("Liste
 * archivée"), `deleted` for a deleted list ("Liste supprimée"), which comes back when one of
 * its tasks is restored. Later versions may add states (`x-extensible-enum`).
 */
export type ListStateValue = string;

/**
 * The list of an archived or trashed task, with its name and state as they are now.
 */
export interface ListRef {
  id: string;
  spaceId: string;
  /** "Nom", 80 characters at most. */
  name: string;
  state: ListStateValue;
}

/**
 * A task of the archives ("Archives", tab "Tâches"): the root of a subtree archived together,
 * which comes back together.
 */
export interface ArchivedTask {
  task: TaskSummary;
  list: ListRef;
  /**
     * The subtasks archived with it, at every level.
     * @minimum 0
     */
  subtaskCount: number;
  /** "archivée le 5 nov." */
  archivedAt: string;
  archivedBy: Actor;
}

/**
 * One element of the trash ("Corbeille"): a task and its subtasks at every level, deleted
 * together, which come back or are erased together. Deleting a subtask makes an entry of its
 * own subtree; deleting a list or a space makes one entry per top-level task.
 */
export interface TrashEntry {
  id: string;
  task: TaskRef;
  /**
     * The parent the root had when it was deleted ("Sous-tâche de CAD-482"); `null` for a
     * top-level task.
     */
  parentKey: TaskKey | null;
  /**
     * The subtasks deleted with it, at every level ("Avec 3 sous-tâches").
     * @minimum 0
     */
  subtaskCount: number;
  list: ListRef;
  /** "Supprimée il y a 2 jours" */
  trashedAt: string;
  trashedBy: Actor;
  /**
     * When the entry is erased for good, 30 days after `trashedAt` ("Effacée définitivement
     * dans 28 jours").
     */
  purgeAt: string;
}

/**
 * What a restoration brought back ("CAD-452 restaurée", "Avec 2 sous-tâches, de retour dans
 * Sprint 14.").
 */
export interface TrashRestored {
  task: Task;
  list: TaskList;
  /**
     * The subtasks that came back with it, at every level.
     * @minimum 0
     */
  subtaskCount: number;
  /**
     * Whether the root left its parent, which is no longer live or can no longer take it
     * (", détachée de son parent supprimé"); it is then a top-level task.
     */
  detached: boolean;
  /** Whether its list, deleted, came back with it, at the end of its space. */
  listRestored: boolean;
  /** Whether the space of that list, deleted, came back too, at the end of the sidebar. */
  spaceRestored: boolean;
}

/**
 * What "Vider la corbeille" took out ("Corbeille vidée", "12 éléments effacés définitivement.").
 */
export interface TrashEmptied {
  /**
     * Entries that left the trash, to be erased for good.
     * @minimum 0
     */
  entryCount: number;
}

/**
 * What the realtime gateway needs to let a socket join the room of a list or a task: the role
 * of the actor and where the list or the task is.
 */
export interface AccessCheck {
  role: AccessRoleValue;
  spaceId: string;
  /** The list checked, or the list of the task checked. */
  listId: string;
  /** The task checked; `null` for a list. */
  taskKey: TaskKey | null;
}

